from google.cloud import speech

def get_speech_client():
    return speech.SpeechClient()

def get_recognition_config(language_code):
    return speech.RecognitionConfig(language_code=language_code)

def get_recognition_audio(uri):
    return speech.RecognitionAudio(uri=uri)

def normalize_transcription_response(response):
    return {
        'transcript': response.results[0].alternatives[0].transcript,
        'confidence': response.results[0].alternatives[0].confidence,
    }

def normalize_diarization_response(response):
    return {
        'speaker_labels': [label.speaker_tag for label in response.speaker_labels],
    }

def normalize_timestamped_response(response):
    return {
        'timestamps': [(word.start_time, word.end_time) for word in response.results[0].alternatives[0].words],
    }

from gensim.summarization import summarize

def archive_summary(transcript):
    return summarize(transcript)

from google.cloud import speech

def poll_transcription(job_id):
    client = speech.SpeechClient()
    operation = client.get_operation(name=job_id)
    if operation.done:
        response = operation.result()
        return normalize_transcription_response(response)
    else:
        return {'status': 'IN_PROGRESS'}

from google.cloud import speech

def diarized_transcript(payload):
    client = speech.SpeechClient()
    operation = client.long_running_recognize(
        config=speech.RecognitionConfig(
            language_code=payload['language_code'],
            enable_speaker_diarization=True,
        ),
        audio=speech.RecognitionAudio(uri=payload['audio_uri']),
    )
    response = operation.result()
    return normalize_diarization_response(response)

from google.cloud import speech

def timestamped_transcript(payload):
    client = speech.SpeechClient()
    operation = client.long_running_recognize(
        config=speech.RecognitionConfig(
            language_code=payload['language_code'],
            enable_word_time_offsets=True,
        ),
        audio=speech.RecognitionAudio(uri=payload['audio_uri']),
    )
    response = operation.result()
    return normalize_timestamped_response(response)
